begin;
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',m; end if; end$$;
create function pg_temp.denied(q text) returns void language plpgsql as $$begin begin execute q; exception when others then return; end; raise exception 'Expected rejection: %',q; end$$;
insert into auth.users(id,email_confirmed_at) select ('78000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now() from generate_series(1,4)n;
insert into public.staff_roles(user_id,role) values('78000000-0000-4000-8000-000000000003','admin'),('78000000-0000-4000-8000-000000000004','membership_reviewer');
insert into public.talent_profiles(id,data) values('operations-provider','{"name":"Synthetic Operations Provider","linkedinUrl":"https://www.linkedin.com/in/operations-provider"}');
insert into private.talent_owners(profile_id,user_id) values('operations-provider','78000000-0000-4000-8000-000000000002');
insert into private.market_projects(id,buyer_id,provider_id,status,brief,agreement_version,buyer_agreed,provider_agreed,agreement) values('78000000-0000-4000-8000-000000000010','78000000-0000-4000-8000-000000000001','78000000-0000-4000-8000-000000000002','active','{"title":"Synthetic project"}',1,1,1,'{"approach":"Original immutable funded scope"}');
insert into private.market_milestones(id,project_id,position,terms,funded,submission_version,submission,submitted_at) values('78000000-0000-4000-8000-000000000011','78000000-0000-4000-8000-000000000010',1,'{"title":"Funded board","serviceAmount":1000,"materialsAmount":100}',true,1,'{"delivery":"Sources"}',now()-interval '8 days');
select pg_temp.ok(public.market_process_reminders()>=2,'both reminder stages recorded');
select pg_temp.ok((select count(*)=4 from private.market_milestone_notices where milestone_id='78000000-0000-4000-8000-000000000011'),'two stages for two participants');
select public.market_process_reminders();
select pg_temp.ok((select count(*)=4 from private.market_milestone_notices where milestone_id='78000000-0000-4000-8000-000000000011'),'reminders deduplicated');
select pg_temp.denied($q$update private.market_milestones set submission_version=2 where id='78000000-0000-4000-8000-000000000011'$q$);
select id as case_id from private.market_review_cases where milestone_id='78000000-0000-4000-8000-000000000011' \gset
set local role authenticated;
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000004',true);
select pg_temp.denied('select public.market_case_reviewer_options()');
select pg_temp.denied(format('select public.market_case_detail(%L)',:'case_id'));
select pg_temp.ok(jsonb_array_length(public.market_milestone_notices())=0,'outsider notices private');
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000003',true);
select pg_temp.denied(format('select public.market_case_detail(%L)',:'case_id'));
select pg_temp.denied(format('select public.market_case_action(%L,''assign'',''Independent review assignment'',''78000000-0000-4000-8000-000000000001'')',:'case_id'));
select pg_temp.ok(jsonb_array_length(public.market_case_reviewer_options())>=2,'admin receives named reviewer choices');
select pg_temp.ok(public.market_case_reviewer_options()::text not like '%@%','reviewer choices omit private emails');
select public.market_case_action(:'case_id','assign','Independent reviewer assignment','78000000-0000-4000-8000-000000000004');
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000004',true);
select pg_temp.ok(public.market_case_detail(:'case_id')->'milestone'->>'id'='78000000-0000-4000-8000-000000000011','assigned reviewer sees case');
reset role;
delete from public.staff_roles where user_id='78000000-0000-4000-8000-000000000004';
set local role authenticated;
select pg_temp.denied(format('select public.market_case_detail(%L)',:'case_id'));
select pg_temp.denied(format('select public.market_case_action(%L,''resume_review'',''No longer authorised staff'')',:'case_id'));
reset role;
insert into public.staff_roles(user_id,role) values('78000000-0000-4000-8000-000000000004','membership_reviewer');
set local role authenticated;
select public.market_case_action(:'case_id','resume_review','Parties should review delivery against their agreement');
select pg_temp.denied(format('select public.market_case_detail(%L)',:'case_id'));
reset role;
select pg_temp.ok((select not mediation and not disputed and buyer_accepted is null and provider_accepted is null and not paid from private.market_milestones where id='78000000-0000-4000-8000-000000000011'),'resolution never accepts or pays');
set local role authenticated;
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000004',true);
select pg_temp.denied($q$select public.market_amendments('78000000-0000-4000-8000-000000000010')$q$);
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000001',true);
select public.market_amendment_action('78000000-0000-4000-8000-000000000010','propose',null,'{"approach":"Additional sensor","schedule":"One week","ipTerms":"Additional editable source","confidentiality":"Private","revisions":1,"milestones":[{"title":"Sensor","deliverables":"Source","acceptance":"Tests pass","serviceAmount":300,"materialsAmount":20}]}')->0->>'id' as amendment_id \gset
select public.market_amendment_action('78000000-0000-4000-8000-000000000010','accept',:'amendment_id');
reset role;
select pg_temp.denied($q$update private.market_projects set agreement_version=2 where id='78000000-0000-4000-8000-000000000010'$q$);
select pg_temp.ok((select count(*)=1 from private.market_milestones where project_id='78000000-0000-4000-8000-000000000010'),'one acceptance does not add work');
select set_config('armature.local_market_simulator','on',true);
select pg_temp.denied($q$select public.market_simulate_payment('78000000-0000-4000-8000-000000000011','payout')$q$);
set local role authenticated;
select set_config('request.jwt.claim.sub','78000000-0000-4000-8000-000000000002',true);
select public.market_amendment_action('78000000-0000-4000-8000-000000000010','accept',:'amendment_id');
select pg_temp.denied(format('select public.market_amendment_action(''78000000-0000-4000-8000-000000000010'',''accept'',%L)',:'amendment_id'));
reset role;
select pg_temp.ok((select agreement_version=2 and buyer_agreed=2 and provider_agreed=2 and agreement->>'approach'='Original immutable funded scope' from private.market_projects where id='78000000-0000-4000-8000-000000000010'),'new version preserves funded agreement');
select pg_temp.ok((select count(*)=2 from private.market_milestones where project_id='78000000-0000-4000-8000-000000000010'),'mutual addition applied once');
select pg_temp.ok((select terms->>'serviceAmount'='1000' and funded and not paid from private.market_milestones where id='78000000-0000-4000-8000-000000000011'),'funded terms unchanged');
select pg_temp.ok((select count(*)=3 from private.market_case_audit where case_id=:'case_id'),'assignment access and resolution audited');
select pg_temp.denied($q$update private.market_projects set brief='{"budget_min":2000,"budget_max":1000}' where id='78000000-0000-4000-8000-000000000010'$q$);
select pg_temp.denied($q$update private.market_projects set brief='{"budget_min":"1 lakh","budget_max":100000}' where id='78000000-0000-4000-8000-000000000010'$q$);
select pg_temp.denied($q$update private.market_projects set brief='{"skills":[123]}' where id='78000000-0000-4000-8000-000000000010'$q$);
update private.market_projects set brief='{"skills":"CAD, ROS","budget":"To discuss"}' where id='78000000-0000-4000-8000-000000000010';
update private.market_projects set brief='{"skills":["CAD","ROS"],"budget_min":1000,"budget_max":2000}' where id='78000000-0000-4000-8000-000000000010';
rollback;
